def pages_from_pdf(root, name):
    """The section map with each heading's page looked up in the rebuilt PDF; a heading not found keeps its old page."""
    import fitz
    with fitz.open(root / f'{name}.pdf') as pdf:
        texts = [' '.join(p.get_text().split()) for p in pdf]
    out = []
    for section in SECTIONS[name]:
        heading = ' '.join(section['heading'].split())
        found = next((n for n, t in enumerate(texts, 1) if heading in t and not (heading == 'IMOBX' and n > 1)), section['page'])
        out.append(dict(section, page=found))
    return out


def build_gateway(root, page, tr, esc, item, name, title, sections=None):
    """Write <name>.html: what the document is, its downloads and its sections."""
    def text(pair, tag='p', attrs=''):
        return tr(*pair, tag, attrs)
    body = '<main class="paper archive-gateway" id="main"><span id="top"></span>'
    body += text((item['pt'], item['en']), 'h1')
    body += text((item['description_pt'], item['description_en']))
    body += text((LABEL_PT + ' · documento em inglês', LABEL_EN + ' · English document'), 'p', 'class="resource-meta"')
    body += '<p class="archive-downloads">' + ' · '.join(
        text((pt, en), 'a', f'href="{esc(target)}" download') for target, pt, en in item['links'] if not target.endswith('.html')) + '</p>'
    body += text(('Seções do documento', 'Document sections'), 'h2') + '<ol class="archive-sections">'
    for section in sections or SECTIONS[name]:
        anchors = ''.join(f'<span id="{esc(i)}"></span>' for i in section['ids'][1:])
        body += f'<li id="{esc(section["ids"][0])}">{anchors}<strong lang="en">{esc(section["heading"])}</strong> '
        body += text((f'PDF, página {section["page"]}', f'PDF, page {section["page"]}'), 'a',
                     f'href="{name}.pdf#page={section["page"]}"') + '</li>'
    body += '</ol>' + text(('Todos os documentos', 'All documents'), 'a', 'href="resources.html"') + '</main>'
    (root / f'{name}.html').write_text(page(title, body, '<script src="assets/site.js" defer></script>',
                                            lang='pt-BR', title_pt=title))
